import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxCard,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type Status = 'active' | 'paused' | 'overrun';

type Project = {
  id: string;
  name: string;
  usedPercent: number;
  status: Status;
};

const STATUS_META: Record<Status, { label: string; tone: 'success' | 'neutral' | 'danger' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'neutral' },
  overrun: { label: 'Превышение', tone: 'danger' },
};

const STATUS_ORDER: Status[] = ['active', 'paused', 'overrun'];

const PAGE_SIZE = 5;

const DEFAULT_PROJECTS: Project[] = [
  { id: 'atlas', name: 'Atlas Ingest', usedPercent: 82, status: 'active' },
  { id: 'borealis', name: 'Borealis Billing', usedPercent: 118, status: 'overrun' },
  { id: 'cinder', name: 'Cinder Search', usedPercent: 41, status: 'active' },
  { id: 'delta', name: 'Delta Reporting', usedPercent: 0, status: 'paused' },
  { id: 'echo', name: 'Echo Notifications', usedPercent: 67, status: 'active' },
  { id: 'fjord', name: 'Fjord Data Lake', usedPercent: 94, status: 'active' },
  { id: 'glint', name: 'Glint Analytics', usedPercent: 12, status: 'paused' },
  { id: 'harbor', name: 'Harbor Gateway', usedPercent: 103, status: 'overrun' },
  { id: 'iris', name: 'Iris Recommendations', usedPercent: 58, status: 'active' },
  { id: 'juno', name: 'Juno Exports', usedPercent: 29, status: 'paused' },
  { id: 'kelp', name: 'Kelp Media', usedPercent: 76, status: 'active' },
  { id: 'larch', name: 'Larch Archive', usedPercent: 5, status: 'paused' },
];

export default function ProjectSpendPanel({
  projects = DEFAULT_PROJECTS,
}: {
  projects?: Project[];
}) {
  const [selected, setSelected] = useState<Status[]>([]);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => (selected.length === 0 ? projects : projects.filter((p) => selected.includes(p.status))),
    [projects, selected],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const rows = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: Status) => {
    setSelected((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setSelected([]);
    setPage(1);
  };

  return (
    <JxCard>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
        <div
          role="group"
          aria-label="Фильтр по статусу"
          style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
        >
          {STATUS_ORDER.map((status) => {
            const active = selected.includes(status);
            return (
              <JxChip
                key={status}
                selected={active}
                aria-pressed={active}
                onClick={() => toggleStatus(status)}
              >
                {STATUS_META[status].label}
              </JxChip>
            );
          })}
        </div>

        {rows.length === 0 ? (
          <JxEmptyState
            title="Нет проектов под выбранные фильтры"
            description="Снимите часть фильтров по статусу, чтобы увидеть расход по проектам."
            action={
              <JxButton variant="primary" onClick={resetFilters}>
                Сбросить фильтры
              </JxButton>
            }
          />
        ) : (
          <>
            <ul
              style={{
                listStyle: 'none',
                margin: 0,
                padding: 0,
                display: 'flex',
                flexDirection: 'column',
                gap: 'var(--jx-space-2)',
              }}
            >
              {rows.map((project) => {
                const meta = STATUS_META[project.status];
                return (
                  <li
                    key={project.id}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: 'var(--jx-space-3)',
                      padding: 'var(--jx-space-3)',
                      borderBottom: '1px solid var(--jx-color-border)',
                    }}
                  >
                    <JxProgressCircle
                      value={Math.min(project.usedPercent, 100)}
                      max={100}
                      tone={meta.tone}
                      aria-label={`Квота ${project.name}: ${project.usedPercent}%`}
                    />
                    <span style={{ flex: 1, minWidth: 0 }}>{project.name}</span>
                    <span style={{ color: 'var(--jx-color-text-muted)' }}>
                      {project.usedPercent}%
                    </span>
                    <JxBadge tone={meta.tone}>{meta.label}</JxBadge>
                  </li>
                );
              })}
            </ul>

            <JxPagination page={currentPage} pageCount={pageCount} onPageChange={setPage} />
          </>
        )}
      </div>
    </JxCard>
  );
}

